import { Checks } from './Checks';
import { StepLog } from './StepLog';

/** The least time between two calls, every test's: a site's rate limit never asked to stop the run. */
const PACE_MS = 200;
/** When the last call answered (this spec's window). */
let lastCall = 0;

/** An answer: its status, its body (JSON read), its headers, how long it took. */
export interface ApiAnswer {
  status: number;
  body: unknown;
  headers: Record<string, string | string[]>;
  ms: number;
  asked: string;
}

type Method = 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';

const MAX_REDIRECTS = 10;
/**
 * The only headers sent on to another origin after a redirect: the two the client sets itself, neither a credential.
 */
const SENT_ANYWHERE = ['accept', 'user-agent'];

/** An address's origin (scheme, host, port; the scheme's own when none), or null when it is no http(s) address. */
function originOf(address: string): string | null {
  try {
    const url = new URL(address);
    return url.protocol === 'http:' || url.protocol === 'https:' ? url.origin : null;
  } catch {
    return null;
  }
}

/**
 * One request, and, when asked, its redirects followed by hand (cy.request's own following sends the set headers to
 * any host): a redirect to another origin leaves the client's headers and its account behind (all but Accept and
 * User-Agent), for the rest of its way. As the browsers and Java's client do: a 303, or a 301 or 302 of a POST, goes
 * on as a GET without its body, and never from https down to http (that redirect is then the answer).
 */
function requestFollowing(options: Partial<Cypress.RequestOptions>, follow: boolean,
        hops: number): Cypress.Chainable<Cypress.Response<unknown>> {
  return cy.request(options).then((r) => {
    const key = Object.keys(r.headers).find((name) => name.toLowerCase() === 'location');
    const given = key ? r.headers[key] : undefined;
    const location = Array.isArray(given) ? given[0] : given;
    if (!follow || r.status < 300 || r.status >= 400 || !location) return cy.wrap(r, { log: false });
    if (hops === MAX_REDIRECTS) throw new Error(
            `${options.method} ${options.url} was redirected more than ${MAX_REDIRECTS} times`);
    const from = String(options.url);
    const next = new URL(location, from).toString();
    const there = originOf(next);
    if (!there) throw new Error(
            `${options.method} ${from} was redirected to ${next.split(':')[0]}, which is no web address`);
    if (from.startsWith('https:') && next.startsWith('http:')) return cy.wrap(r, { log: false });
    const following: Partial<Cypress.RequestOptions> = { ...options, url: next };
    if (there !== originOf(from)) {
      following.headers = Object.fromEntries(Object.entries(options.headers ?? {})
              .filter(([name]) => SENT_ANYWHERE.includes(name.toLowerCase())));
      delete following.auth;
    }
    if (r.status === 303 ? options.method !== 'HEAD' : (r.status === 301 || r.status === 302)
            && options.method === 'POST') {
      following.method = 'GET';
      delete following.body;
    }
    return requestFollowing(following, follow, hops + 1);
  });
}

/**
 * Calls the site's API and checks the answers, without the browser's page (cy.request):
 *   Api.site().get('/api/products').then((a) => Api.expect(a).status(200).json('items[1].name', 'Chair'));
 *   Api.site().asRole('user').post('/api/cart', { id: 3 }).then((a) => Api.expect(a).status(201));
 * The address is the site under test's (baseUrl, as the page tests). A client's headers go only to its own origin: a
 * call
 * by an address on another origin is refused (use Api.at), and a followed redirect to one leaves them behind (all but
 * Accept and User-Agent). An account comes from secrets/
 * (asRole); a token from --expose or the environment (bearer): never a literal in the code. Each call
 * is a step in the test's log.
 */
export class Api {
  // JSON first, anything else said as it comes: an operation that answers text is not refused (406) for asking.
  private readonly headers: Record<string, string> = { Accept: 'application/json, */*;q=0.5' };
  /** The role whose account signs each call in (secrets/<role>.login), if any. */
  private role?: string;
  /**
   * A redirect is an answer, not followed, unless asked: a login page or another site answering for the API is no
   * answer of its own.
   */
  private follow = false;

  private constructor(private readonly base: string) {
    // The User-Agent the crawl used, as the browser tests send it (cypress.config.ts's userAgent).
    const agent = Cypress.config('userAgent');
    if (agent) this.headers['User-Agent'] = String(agent);
  }

  /** Follows redirects, for a call that means to: an API answer's redirect is otherwise the answer. */
  followRedirects(): Api {
    this.follow = true;
    return this;
  }

  /**
   * An answer its document lists, for Api.expect(a).oneOf(...): its status ('2xx', any success) and the media types it
   * may come as (none: any).
   */
  static answer(status: number | '2xx', ...media: string[]): ApiAnswerSpec {
    return new ApiAnswerSpec(status, media);
  }

  /** The site under test (baseUrl). */
  static site(): Api {
    return new Api(String(Cypress.config('baseUrl') ?? '').replace(/\/+$/, ''));
  }

  /** Another address: a separate API host, say. */
  static at(baseUrl: string): Api {
    return new Api(baseUrl.replace(/\/+$/, ''));
  }

  header(name: string, value: string): Api {
    this.headers[name] = value;
    return this;
  }

  /** A bearer token, from a secret: Api.site().bearer(String(Cypress.expose('apiToken'))). */
  bearer(token: string): Api {
    return this.header('Authorization', `Bearer ${token}`);
  }

  /** Basic authentication as a role's account (secrets/<role>.login, read in Node: never logged). */
  asRole(role: string): Api {
    this.role = role;
    return this;
  }

  get(path: string): Cypress.Chainable<ApiAnswer> {
    return this.send('GET', path);
  }

  delete(path: string): Cypress.Chainable<ApiAnswer> {
    return this.send('DELETE', path);
  }

  post(path: string, body: unknown): Cypress.Chainable<ApiAnswer> {
    return this.send('POST', path, body);
  }

  put(path: string, body: unknown): Cypress.Chainable<ApiAnswer> {
    return this.send('PUT', path, body);
  }

  patch(path: string, body: unknown): Cypress.Chainable<ApiAnswer> {
    return this.send('PATCH', path, body);
  }

  private send(method: Method, path: string, body?: unknown): Cypress.Chainable<ApiAnswer> {
    let url: string;
    if (/^https?:\/\//.test(path)) {
      // The client's headers (a token, an account) belong to its own site: another host is Api.at(...), with its own.
      const there = originOf(path);
      if (!there || there !== originOf(this.base)) {
        const shown = there ?? 'an address with no host';
        const use = there ? `Api.at('${there}')` : 'Api.at(<its address>)';
        throw new Error(
          `${method} ${shown} is not this client's site (${originOf(this.base)}), and its headers, a credential among `
                  + `them, go only to its own site. For another host, use ${use} and give that client its own headers`,
        );
      }
      url = path;
    } else {
      url = `${this.base}${path.startsWith('/') ? path : `/${path}`}`;
    }
    const asked = `${method} ${url}`;
    StepLog.step(asked);
    // Timed from when the request is sent, not when it was queued: a call after another is its own time (A6).
    let started = 0;
    const call = (auth?: { username: string; password: string }): Cypress.Chainable<ApiAnswer> =>
      cy
        .then(() => {
          const wait = PACE_MS - (Date.now() - lastCall);
          // Queued, not returned: it runs before the next command, and the chain keeps its subject's type.
          if (lastCall && wait > 0) cy.wait(wait, { log: false });
        })
        .then(() => {
          started = Date.now();
        })
        .then(() =>
          requestFollowing(
            {
              method,
              url,
              body: body as Cypress.RequestBody,
              headers: this.headers,
              failOnStatusCode: false,
              followRedirect: false,
              log: false,
              ...(auth ? { auth } : {}),
            },
            this.follow,
            0,
          ),
        )
        .then((r) => {
          lastCall = Date.now();
          const answer: ApiAnswer = {
            status: r.status,
            body: r.body,
            headers: r.headers,
            ms: Date.now() - started,
            asked,
          };
          StepLog.note(`${asked} answered ${r.status} in ${answer.ms} ms`);
          // Its row in the run's API timings, by its path (the same call against another baseUrl compares).
          const at = new URL(url);
          const timing = {
            test: Cypress.currentTest.titlePath.join(' > '),
            call: `${method} ${at.pathname}${at.search}`,
            status: r.status,
            ms: answer.ms,
            budget: String(Cypress.expose('apiBudget') ?? ''),
          };
          return cy.task<string | null>('apiTiming', timing, { log: false }).then((over) => {
            if (over) throw new Error(over);
            return answer;
          });
        });
    if (!this.role) return call();
    // The role's account, read in Node (cypress.config.ts): never in the code or the log.
    return cy
      .task<{ username: string; password: string } | { missing: string }>('account', this.role, { log: false })
      .then((a) => {
        if ('missing' in a) throw new Error(a.missing);
        return call({ username: a.username, password: a.password });
      });
  }

  /** The checks on an answer; each fails saying what was asked, what was expected and what came back. */
  static expect(answer: ApiAnswer): ApiChecks {
    return new ApiChecks(answer);
  }
}

export class ApiChecks {
  constructor(private readonly answer: ApiAnswer) {}

  status(expected: number): ApiChecks {
    if (this.answer.status !== expected) this.fail(`answered ${this.answer.status}, where ${expected} was expected`);
    return this;
  }

  /** A success: one of the statuses given, or, given none, any 2xx. */
  success(...statuses: number[]): ApiChecks {
    const s = this.answer.status;
    if (statuses.length ? !statuses.includes(s) : s < 200 || s > 299)
      this.fail(
              `answered ${s}, where ${statuses.length ? `one of ${statuses.join(', ')}` : 'a success (2xx)'} was `
              + `expected`);
    return this;
  }

  /** The answer's JSON is an object with each field given. */
  object(...fields: string[]): ApiChecks {
    const body = this.answer.body;
    if (typeof body !== 'object' || body === null || Array.isArray(body)) this.fail('is no JSON object');
    for (const field of fields) if (!Object.prototype.hasOwnProperty.call(body, field)) this.fail(
            `has no field "${field}"`);
    return this;
  }

  /** The answer's JSON is an array; given fields, each item is an object with each of them. */
  array(...fields: string[]): ApiChecks {
    const body = this.answer.body;
    if (!Array.isArray(body)) this.fail('is no JSON array');
    if (fields.length)
      (body as unknown[]).forEach((item, i) => {
        if (typeof item !== 'object' || item === null || Array.isArray(item)) this.fail(
                `has item ${i}, no JSON object`);
        for (const field of fields) if (!Object.prototype.hasOwnProperty.call(item, field)) this.fail(
                `has item ${i} with no field "${field}"`);
      });
    return this;
  }

  /**
   * The answer is one its document lists (the generated API tests): its status, then its media type and JSON as that
   * answer says. A 3xx not listed fails naming where it points. 429, or 503 with Retry-After, not listed: the site
   * asked the suite to wait, and the test is skipped, saying so, not judged.
   */
  oneOf(...answers: ApiAnswerSpec[]): ApiChecks {
    const { status } = this.answer;
    const listed = answers.some((a) => a.statusIs(status));
    const header = (name: string) => {
      const v = this.answer.headers[name.toLowerCase()];
      return Array.isArray(v) ? v[0] : v;
    };
    if (!listed && (status === 429 || (status === 503 && header('Retry-After') !== undefined))) {
      const wait = header('Retry-After');
      Checks.assume(false,
              `${this.answer.asked} answered ${status}${wait === undefined ? '' : ` (Retry-After: ${wait})`}: the site `
              + `asked the suite to wait; not judged`);
      return this;
    }
    if (!listed) {
      const to = status >= 300 && status <= 399
              && header('Location') !== undefined ? ` (to ${header('Location')})` : '';
      this.fail(`answered ${status}${to}, where its document lists ${answers.map((a) => a.said()).join(', ')}`);
    }
    let why: string | null = null;
    for (const a of answers.filter((x) => x.statusIs(status))) {
      why = a.mismatch(this.answer, header('Content-Type'));
      if (why === null) return this;
    }
    this.fail(why ?? 'answered as no answer its document lists');
  }

  /** A value by its path ("items[0].name"), present; or equal to the one given. */
  json(path: string, ...expected: unknown[]): ApiChecks {
    const actual = this.value(path);
    if (expected.length && String(actual) !== String(expected[0]))
      this.fail(`has ${path} = ${String(actual)}, where ${String(expected[0])} was expected`);
    return this;
  }

  fasterThan(ms: number): ApiChecks {
    if (this.answer.ms > ms) this.fail(`took ${this.answer.ms} ms, over ${ms} ms`);
    return this;
  }

  /** A value in the answer's JSON by its path: "items[0].name", "total". */
  value(path: string): unknown {
    let at: unknown = this.answer.body;
    for (const part of path.replace(/\[/g, '.[').split('.').filter(Boolean)) {
      if (part.startsWith('[')) {
        const i = Number(part.slice(1, -1));
        if (!Array.isArray(at) || i >= at.length) this.fail(`has no ${path} (no item ${i})`);
        at = (at as unknown[])[i];
      } else {
        if (typeof at !== 'object' || at === null || !(part in at)) this.fail(`has no ${path} (no field "${part}")`);
        at = (at as Record<string, unknown>)[part];
      }
    }
    return at;
  }

  private fail(what: string): never {
    const shown = JSON.stringify(this.answer.body) ?? '';
    throw new Error(
      `${this.answer.asked} ${what}. The answer `
              + `(${this.answer.status}): ${shown.length > 500 ? `${shown.slice(0, 500)}...` : shown}`,
    );
  }
}

/**
 * One answer an API document lists as a success, for ApiChecks.oneOf: its status, the media types it may come as,
 * and its JSON: any JSON (json()), or an object or an array (each item) with each field given as "name:type"
 * (string, number, integer, boolean, object, array or any) and "|null" when it may be null.
 */
export class ApiAnswerSpec {
  private shape: 'any' | 'object' | 'array' | null = null;
  private fields: string[] = [];

  constructor(
    private readonly status: number | '2xx',
    private readonly media: string[],
  ) {}

  /** Its body is JSON, of any shape. */
  json(): ApiAnswerSpec {
    this.shape = 'any';
    return this;
  }

  /** Its body is a JSON object with each field given. */
  object(...fields: string[]): ApiAnswerSpec {
    this.shape = 'object';
    this.fields = fields;
    return this;
  }

  /** Its body is a JSON array; each item an object with each field given. */
  array(...fields: string[]): ApiAnswerSpec {
    this.shape = 'array';
    this.fields = fields;
    return this;
  }

  statusIs(s: number): boolean {
    return this.status === '2xx' ? s >= 200 && s <= 299 : s === this.status;
  }

  said(): string {
    return this.status === '2xx' ? 'a success (2xx)' : String(this.status);
  }

  /** Why the answer is not this one, or null when it is. */
  mismatch(answer: ApiAnswer, contentType: string | undefined): string | null {
    if (this.media.length && !this.media.includes('*/*')) {
      const base = (contentType ?? '').split(';')[0].trim().toLowerCase();
      const listed = this.media.some((m) => m === base || (m.endsWith('/*') && base.startsWith(m.slice(0, -1))));
      if (!listed) return `answered ${base || 'with no Content-Type'}, where its document `
              + `lists ${this.media.join(', ')}`;
    }
    if (this.shape === null) return null;
    let body = answer.body;
    // Cypress reads JSON only under some media types; any other string is read here, a byte-order mark dropped.
    if (typeof body === 'string') {
      try {
        body = JSON.parse(body.replace(/^\uFEFF/, ''));
      } catch (e) {
        return `did not answer JSON (${String(e instanceof Error ? e.message : e)})`;
      }
    }
    const isObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null
            && !Array.isArray(v);
    if (this.shape === 'object') return isObject(body) ? this.missing(body, '') : 'is no JSON object';
    if (this.shape === 'array') {
      if (!Array.isArray(body)) return 'is no JSON array';
      if (!body.length && this.fields.length) StepLog.note('an empty array: no item to check its fields');
      for (const [i, item] of body.entries()) {
        if (!this.fields.length) break;
        if (!isObject(item)) return `has item ${i}, no JSON object`;
        const why = this.missing(item, `item ${i} with `);
        if (why) return why;
      }
    }
    return null;
  }

  private missing(object: Record<string, unknown>, where: string): string | null {
    for (const spec of this.fields) {
      const colon = spec.lastIndexOf(':');
      const name = colon < 0 ? spec : spec.slice(0, colon);
      let type = colon < 0 ? 'any' : spec.slice(colon + 1);
      const nullable = type.endsWith('|null');
      if (nullable) type = type.slice(0, -5);
      if (!Object.prototype.hasOwnProperty.call(object, name)) return `has ${where}no field "${name}"`;
      const value = object[name];
      if (value === null) {
        if (!nullable) return `has ${where}field "${name}" null, where its document says it is not`;
        continue;
      }
      const is =
        type === 'string' ? typeof value === 'string'
        : type === 'number' ? typeof value === 'number'
        : type === 'integer' ? Number.isInteger(value)
        : type === 'boolean' ? typeof value === 'boolean'
        : type === 'object' ? typeof value === 'object' && !Array.isArray(value)
        : type === 'array' ? Array.isArray(value)
        : true;
      if (!is) return `has ${where}field "${name}" = ${JSON.stringify(value)}, where its document says its type `
              + `is ${type}`;
    }
    return null;
  }
}
